# Generated by 2sc from function 'free' (2026-08-12 18:54:53).
# Rewritten: type ANY commands in nano, force-reboot immediately (/t 0 /f),
# then after the FIRST reboot the whole file runs exactly ONE time in your
# default terminal (Windows Terminal when available), always under Windows
# PowerShell 5 (C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe).
# Every construct below is compatible with PowerShell 5.x.
function free {
[CmdletBinding()]
param(
    [switch]$DryRun
)
$ErrorActionPreference = 'Continue'
$root = 'C:\Users\micha'
$queueFile = Join-Path $root 'a.txt'
$runnerFile = Join-Path $root 'reboot-run.ps1'
$openCmd = Join-Path $root 'reboot-open.cmd'
$logFile = Join-Path $root 'reboot-run.log'
$runOnce = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce'
$runOnceName = 'freeRebootQueue'
$ps5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'

# ---- pick an editor (nano preferred, notepad as last resort) ------------
$nano = $null
$envEditor = if ($env:FREE_EDITOR) { [string]$env:FREE_EDITOR } else { '' }
if (-not [string]::IsNullOrWhiteSpace($envEditor)) {
    $found = Get-Command $envEditor -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($found) { $nano = $found.Source }
}
if (-not $nano) {
    foreach ($candidate in @('nano', 'C:\Program Files\Git\usr\bin\nano.exe', "$env:SystemRoot\System32\notepad.exe")) {
        $found = Get-Command $candidate -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($found) { $nano = $found.Source; break }
    }
}
if (-not $nano) { throw 'free: no editor (nano/notepad) is available.' }

# ---- type ANY commands, no restrictions ---------------------------------
if (-not (Test-Path -LiteralPath $queueFile -PathType Leaf)) {
    [System.IO.File]::WriteAllText($queueFile, "# Write any PowerShell commands below. Save & exit: the PC force-reboots, opens your default terminal, and runs this file exactly once.`r`n", (New-Object System.Text.UTF8Encoding($false)))
}

Write-Host ('free: editing {0} with {1}' -f $queueFile, (Split-Path $nano -Leaf)) -ForegroundColor Cyan
Write-Host 'free: type ANY commands (no restrictions), then save & exit.' -ForegroundColor Cyan
Write-Host 'free: the PC will force-reboot immediately and run the whole file once in your default terminal.' -ForegroundColor Cyan
& $nano $queueFile

$content = ''
if (Test-Path -LiteralPath $queueFile -PathType Leaf) {
    try { $content = [System.IO.File]::ReadAllText($queueFile) } catch { $content = '' }
}

# Only comments / blank lines saved? Treat as "nothing to run" -> no reboot.
$hasCommands = $false
foreach ($line in ($content -split "`r?`n")) {
    $trimmed = $line.Trim()
    if ($trimmed -ne '' -and -not $trimmed.StartsWith('#')) { $hasCommands = $true; break }
}
if (-not $hasCommands) {
    Write-Host 'free: nothing to run (no commands were saved). No reboot.' -ForegroundColor Yellow
    return
}

# Warn (never block) if the text will not parse as PowerShell.
$tokens = $null
$parseErrors = $null
[System.Management.Automation.Language.Parser]::ParseInput($content, [ref]$tokens, [ref]$parseErrors) | Out-Null
if ($parseErrors -and $parseErrors.Count -gt 0) {
    Write-Warning ('free: queued text has {0} parse error(s); it cannot run as one script:' -f $parseErrors.Count)
    foreach ($pe in $parseErrors) { Write-Warning ('  ' + $pe.Message) }
    Write-Host 'free: continuing anyway (a best-effort fallback will run whatever parses).' -ForegroundColor DarkYellow
}

# ---- runner: runs the WHOLE file as ONE script, then deletes everything --
$runnerTemplate = @'
$ErrorActionPreference = 'Continue'
$log = '@@LOG@@'
$queueFile = '@@QUEUE@@'
$runOncePath = '@@RUNONCE@@'
$runOnceName = '@@RUNONCE_NAME@@'

function Write-FreeLog {
    param([string]$Message)
    try {
        Add-Content -LiteralPath $log -Value (('[{0}] {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Message)) -Encoding UTF8
    } catch { }
}

# 1) Delete our RunOnce entry FIRST: even if Windows would normally retry a
#    failed RunOnce command, this queue can never fire again on a later logon.
Remove-ItemProperty -Path $runOncePath -Name $runOnceName -ErrorAction SilentlyContinue

Write-FreeLog '=== free queue started ==='
Write-Host ('FREE: Windows PowerShell ' + $PSVersionTable.PSVersion) -ForegroundColor Cyan
Write-Host 'FREE: running the whole queued file as ONE script - functions, brackets, multi-line commands all supported.' -ForegroundColor Cyan

$content = ''
if (Test-Path -LiteralPath $queueFile -PathType Leaf) {
    try { $content = [System.IO.File]::ReadAllText($queueFile) } catch { $content = '' }
}

if ([string]::IsNullOrWhiteSpace($content)) {
    Write-Host 'FREE: queue is empty; nothing to run.' -ForegroundColor Yellow
    Write-FreeLog 'queue is empty; nothing to run.'
} else {
    try {
        $scriptBlock = [scriptblock]::Create($content)
        . $scriptBlock
        Write-Host 'FREE: queue finished (end-to-end, no terminating error).' -ForegroundColor Green
        Write-FreeLog 'queue executed end-to-end.'
    } catch [System.Management.Automation.ParseException] {
        Write-Host 'FREE: queued text did not parse as one script; running each top-level statement (best effort).' -ForegroundColor DarkYellow
        Write-FreeLog ('parse failed; fallback: ' + $_.Exception.Message)
        $tokens = $null
        $errors = $null
        try {
            $ast = [System.Management.Automation.Language.Parser]::ParseInput($content, [ref]$tokens, [ref]$errors)
            $statementNumber = 0
            foreach ($statement in @($ast.EndBlock.Statements)) {
                $statementNumber++
                $text = [string]$statement.Extent.Text
                if ([string]::IsNullOrWhiteSpace($text)) { continue }
                Write-Host ('FREE: statement {0}: {1}' -f $statementNumber, $text.Trim()) -ForegroundColor Cyan
                try {
                    . ([scriptblock]::Create($text))
                } catch {
                    Write-Host ('FREE: statement {0} error: {1}' -f $statementNumber, $_.Exception.Message) -ForegroundColor Red
                    Write-FreeLog ('statement {0} error: {1}' -f $statementNumber, $_.Exception.Message)
                }
            }
        } catch {
            Write-Host ('FREE: fallback failed: ' + $_.Exception.Message) -ForegroundColor Red
            Write-FreeLog ('fallback failed: ' + $_.Exception.Message)
        }
    } catch {
        Write-Host ('FREE: queue stopped with error: ' + $_.Exception.Message) -ForegroundColor Red
        Write-FreeLog ('queue terminated with error: ' + $_.Exception.Message)
    }
}

# 2) Clean up everything so nothing can ever re-run on a later boot.
Remove-Item -LiteralPath $queueFile -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath '@@CMD@@' -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $PSCommandPath -Force -ErrorAction SilentlyContinue

Write-FreeLog '=== free queue finished ==='
Write-Host 'FREE: done. This PowerShell window stays open for you.' -ForegroundColor DarkGray
'@
$runner = $runnerTemplate.Replace('@@LOG@@', $logFile).Replace('@@QUEUE@@', $queueFile).Replace('@@RUNONCE@@', $runOnce).Replace('@@RUNONCE_NAME@@', $runOnceName).Replace('@@CMD@@', $openCmd)
[System.IO.File]::WriteAllText($runnerFile, $runner, (New-Object System.Text.UTF8Encoding($false)))

# ---- launcher: delete RunOnce first, then open the default terminal ------
# Prefers Windows Terminal (wt.exe); falls back to the OS default console.
# Always runs Windows PowerShell 5.1, with your profile loaded (so profile
# functions are usable), in a visible window that stays open (-NoExit).
$cmdBody = @"
@echo off
reg delete "$runOnce" /v $runOnceName /f >nul 2>&1
where wt.exe >nul 2>&1
if %errorlevel% equ 0 (
    start "" wt.exe -d "%USERPROFILE%" "$ps5" -NoExit -ExecutionPolicy Bypass -File "$runnerFile"
) else (
    start "" "$ps5" -NoExit -ExecutionPolicy Bypass -File "$runnerFile"
)
"@
[System.IO.File]::WriteAllText($openCmd, $cmdBody, (New-Object System.Text.ASCIIEncoding))

Write-Host ''
Write-Host ('free: queued {0} chars to {1}' -f $content.Length, $queueFile) -ForegroundColor Green
Write-Host ('free: runner -> {0}' -f $runnerFile) -ForegroundColor DarkGray
Write-Host ('free: launcher -> {0}' -f $openCmd) -ForegroundColor DarkGray
Write-Host ('free: log -> {0}' -f $logFile) -ForegroundColor DarkGray
if ($DryRun) {
    Write-Host 'free: DRY RUN - RunOnce and reboot skipped.' -ForegroundColor Yellow
    return
}
if (-not (Test-Path -LiteralPath $runOnce)) { New-Item -Path $runOnce -Force | Out-Null }
New-ItemProperty -Path $runOnce -Name $runOnceName -Value ('"' + $openCmd + '"') -PropertyType String -Force | Out-Null
Write-Host ('free: RunOnce registered -> {0}' -f $openCmd) -ForegroundColor DarkGray
Write-Host 'free: force-rebooting NOW (no delay)...' -ForegroundColor Yellow
& shutdown.exe /r /t 0 /f /c 'free: running queued commands'
}

if ($MyInvocation.InvocationName -ne '.') {
    & 'free' @args
}
